    private static void require(boolean value,String text){if(!value)throw new IllegalStateException("Creature drops: "+text);}
    private static boolean cleanAttribution(GameController game,ServerPlayer player){
        try{for(var field:LbcIndirectKills.class.getDeclaredFields())if(Map.class.isAssignableFrom(field.getType())){
            field.setAccessible(true);if(((Map<?,?>)field.get(game.items().indirectKills())).containsKey(player))return false;
        }}catch(IllegalAccessException error){throw new IllegalStateException(error);}return true;
    }
    private static net.minecraft.nbt.CompoundTag saved(Entity entity,ServerLevel level){var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,level.registryAccess());entity.saveWithoutId(out);return out.buildResult();}
