    private static LbcCreatureDrops.Kind runtime(LbcCreatureDropItem.Kind kind){return switch(kind){case OLD_VEX->LbcCreatureDrops.Kind.VEX_OLD;case VEX->LbcCreatureDrops.Kind.VEX;case OLD_SKELETON->LbcCreatureDrops.Kind.SKELETON_OLD;case FAT_SKELETON->LbcCreatureDrops.Kind.FAT_SKELETON;case OLD_BOB->LbcCreatureDrops.Kind.BOB_OLD;default->LbcCreatureDrops.Kind.BULLETS;};}
