        void initialize(){var pos=BlockPos.containing(origin);long key=net.minecraft.world.level.ChunkPos.pack(pos.getX()>>4,pos.getZ()>>4);if(!level.getForceLoadedChunks().contains(key)){forced.add(key);level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);}level.getChunkAt(pos);for(var p:List.of(alpha,beta)){p.closeContainer();p.getInventory().clearContent();p.removeAllEffects();p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);p.setAbsorptionAmount(0);reset(p);}alpha.teleportTo(level,origin.x+20,origin.y,origin.z,Set.of(),0,0,true);beta.teleportTo(level,origin.x+22,origin.y,origin.z,Set.of(),0,0,true);level.getGameRules().set(GameRules.MOB_DROPS,true,game.server());lastTick=game.server().getTickCount();}
        void reset(LivingEntity target){target.setInvulnerableTime(0);target.damageCooldownTime=0;}
