        void vex(){var actors=batch(LbcCreatureDropItem.Kind.OLD_VEX);require(actors.size()==5,"five native Vex");for(int i=0;i<5;i++){var entity=actors.get(i);double yaw=Math.toRadians(37+i*72),pitch=Math.toRadians(23);var expected=origin.add(-Math.sin(yaw)*Math.cos(pitch)*3,-Math.sin(pitch)*3,Math.cos(yaw)*Math.cos(pitch)*3);require(entity.getClass()==Vex.class&&entity.position().distanceTo(expected)<1e-3,"source local ring within native Mth trigonometric precision "+i+" actual="+entity.position()+" expected="+expected);var mob=(Vex)entity;require(mob.getHealth()==1&&mob.getMaxHealth()==1&&!mob.isNoAi()&&!mob.isPersistenceRequired(),"native1HP Vex defaults");}guards(actors.getFirst(),false);}
        Cow cow(){var c=new Cow(EntityTypes.COW,level);c.setPos(origin.add(0,4,0));c.setNoAi(true);c.setNoGravity(true);require(level.addFreshEntity(c),"disposable native victim");return c;}
